import React, { useState } from "react";
import axios from "axios";

export default function AdminPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [msg, setMsg] = useState("");

  const login = async (e) => {
    e.preventDefault();
    setMsg("");
    try {
      const { data } = await axios.post("/api/admin/login", { email, password });
      // save token as main token so dashboard recognizes admin user
      localStorage.setItem("roomly_token", data.token);
      localStorage.setItem("roomly_admin_token", data.token);
      axios.defaults.headers.common["Authorization"] = `Bearer ${data.token}`;
      // redirect to dashboard where admin UI lives
      window.location.href = "/dashboard";
    } catch (err) {
      setMsg(err.response?.data?.message || "Login failed.");
    }
  };

  const card = {
    width: 420,
    maxWidth: "92%",
    background: "white",
    padding: 28,
    borderRadius: 12,
    boxShadow: "0 8px 30px rgba(15,15,15,.08)",
    textAlign: "left",
  };

  const input = {
    width: "100%",
    padding: "12px 14px",
    borderRadius: 8,
    border: "1px solid #eee",
    marginBottom: 12,
    fontSize: 14,
  };

  const btn = {
    width: "100%",
    padding: "12px 16px",
    borderRadius: 10,
    border: "none",
    background: "#c9782b",
    color: "white",
    fontSize: 15,
    fontWeight: 600,
    cursor: "pointer",
  };

  return (
    <div style={{ minHeight: "80vh", display: "flex", alignItems: "center", justifyContent: "center", padding: 24 }}>
      <div style={card}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", marginBottom: 6 }}>
          <div style={{ width: 64, height: 64, borderRadius: 999, background: "#FFF5EB", display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 12 }}>
            <svg width="28" height="28" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 12a3 3 0 100-6 3 3 0 000 6z" stroke="#c9782b" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round"/><path d="M20 21v-1a4 4 0 00-4-4H8a4 4 0 00-4 4v1" stroke="#c9782b" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round"/></svg>
          </div>
          <h2 style={{ margin: 0, fontSize: 20 }}>Admin panel</h2>
          <div style={{ fontSize: 13, color: "#7a7a7a", marginTop: 6, marginBottom: 14 }}>Please sign in to continue</div>
        </div>

        <form onSubmit={login}>
          <label style={{ fontSize: 13, fontWeight: 600, marginBottom: 6, display: "block" }}>Email</label>
          <div style={{ position: "relative", marginBottom: 8 }}>
            <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", opacity: 0.6 }}>✉️</span>
            <input style={{ ...input, paddingLeft: 36 }} type="email" placeholder="Enter your email" value={email} onChange={e => setEmail(e.target.value)} required />
          </div>

          <label style={{ fontSize: 13, fontWeight: 600, marginBottom: 6, display: "block" }}>Password</label>
          <div style={{ position: "relative", marginBottom: 14 }}>
            <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", opacity: 0.6 }}>🔒</span>
            <input style={{ ...input, paddingLeft: 36 }} type="password" placeholder="Enter your password" value={password} onChange={e => setPassword(e.target.value)} required />
          </div>

          {msg && <div style={{ color: "#d64545", marginBottom: 10 }}>{msg}</div>}

          <button style={btn} type="submit">Sign in</button>
        </form>
      </div>
    </div>
  );
}
